const staffVersions=['常规版','24版','22版','22版2D','老汉艺版本'];
function localDate(s){if(!s)return '原有名单';return new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})}
function renderCampus(){$('rosterCount').textContent=Object.keys(state.staff).length+' 名员工 · 长期保留';const q=$('staffSearch').value.trim(),meta=campusStore.staffMeta();$('stafflist').innerHTML='<table><thead><tr><th>员工</th><th>绩效版本（可直接修改）</th><th>最近更新</th><th>记录</th></tr></thead><tbody>'+Object.entries(state.staff).filter(([name])=>name.includes(q)).sort(([a],[b])=>a.localeCompare(b,'zh-CN')).map(([name,version])=>`<tr><td>${esc(name)}</td><td><select data-staff-name="${esc(name)}" aria-label="${esc(name)}的绩效版本">${staffVersions.map(v=>`<option ${version===v?'selected':''}>${v}</option>`).join('')}</select></td><td>${esc(localDate(meta[name]?.updatedAt))}</td><td><button data-staff-history="${esc(name)}">查看变更</button></td></tr>`).join('')+(Object.keys(state.staff).length?'':'<tr><td colspan="4">添加或导入员工版本名单，下个月会继续保留。</td></tr>')+'</tbody></table>';const other=state.entries.some(e=>e.month!==$('month').value)||Object.keys(state.salary).some(k=>!k.startsWith($('month').value+'|'));$('periodNotice').classList.toggle('hidden',!other);$('periodText').textContent='检测到其他月份的工资草稿。请先导出需要保留的报表，再开始新一期；员工版本名单会保留。'}
function refreshCampusState(){$('staffSearch').value='';editing=null;importPreview=[];importBook=[];importFile='';reviewSelection=null;$('entryform').reset();$('formtitle').textContent='手动补录';$('importFile').value='';$('fileName').textContent='';$('sheetConfigs').innerHTML='';$('previewBody').innerHTML='';$('importSettings').classList.add('hidden');$('reviewPanel').classList.add('hidden');$('commitImport').disabled=true;$('staffHistory').classList.add('hidden');$('importStats').textContent='请上传本期文件；本地保存的员工名单会自动用于匹配。';$('month').value=campusStore.period()||new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date());populate();render();renderReview()}
const renderBeforeCampus=render;render=function(){renderBeforeCampus();renderCampus()};
$('staffSearch').oninput=renderCampus;
$('stafflist').onchange=e=>{const name=e.target.dataset.staffName;if(!name)return;const prev=state.staff[name];try{state.staff[name]=e.target.value;save();render();toast(name+'的版本已更新；本期已导入记录可点击“按员工名单重新匹配”更新')}catch(err){state.staff[name]=prev;renderCampus();toast(err.message)}};
$('stafflist').onclick=e=>{const name=e.target.dataset.staffHistory;if(!name)return;const history=campusStore.staffMeta()[name]?.history||[];$('staffHistory').classList.remove('hidden');$('staffHistoryTitle').textContent=name+' · 绩效版本变更记录';$('staffHistoryBody').innerHTML=history.length?'<table><tr><th>时间</th><th>原版本</th><th>新版本</th></tr>'+[...history].reverse().map(h=>`<tr><td>${esc(localDate(h.at))}</td><td>${esc(h.from||'首次设置')}</td><td>${esc(h.to)}</td></tr>`).join('')+'</table>':'<p class="muted">这是迁移前的员工名单，尚无版本变更记录。</p>'};
$('staffform').onsubmit=e=>{e.preventDefault();const name=$('staffname').value.trim();if(!name)return;const previous=state.staff[name];try{state.staff[name]=$('staffversion').value;save();render();$('staffname').value='';toast('已保存到本地长期员工名单')}catch(err){if(previous===undefined)delete state.staff[name];else state.staff[name]=previous;toast(err.message)}};
function clearPayrollDraft(){if(!confirm('请确认已导出需要保留的工资报表。清空本地工资草稿与预览，员工及绩效版本名单会保留。'))return;try{state=campusStore.clearDraft($('month').value);refreshCampusState();toast('工资草稿已清理，员工版本名单完整保留')}catch(err){toast(err.message)}}
$('clear').onclick=clearPayrollDraft;$('startNewPeriod').onclick=clearPayrollDraft;
$('month').addEventListener('change',renderCampus);
$('staffExport').onclick=()=>download(JSON.stringify({schema:'campus-staff-v1',campus:campusStore.active().name,staff:state.staff,exportedAt:new Date().toISOString()},null,2),'员工版本名单.json','application/json');
$('staffCSV').onclick=()=>csv([['员工姓名','绩效版本'],...Object.entries(state.staff)],'员工版本名单.csv');
$('staffRestore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const d=JSON.parse(await file.text());if(d.schema!=='campus-staff-v1'||!d.staff||Array.isArray(d.staff)||Object.entries(d.staff).some(([name,v])=>!name.trim()||!staffVersions.includes(v)))throw Error('名单格式不正确');if(!confirm('将名单合并到本地员工名单。同名员工的版本将更新，其他员工及工资草稿保留。继续？'))return;const before={...state.staff};try{state.staff={...state.staff,...d.staff};save();render();toast('员工版本名单已导入')}catch(err){state.staff=before;throw err}}catch(err){toast('名单导入失败：'+err.message)}finally{e.target.value=''}};
renderCampus();
